create or replace function public.wantiss_admin_accept_invitation() returns void language plpgsql security definer set search_path = '' as $$ begin if (select auth.uid()) is null or not exists (select 1 from auth.users u where u.id=(select auth.uid()) and u.email_confirmed_at is not null) then raise exception 'Verified email required' using errcode='42501'; end if; update public.wantiss_admin_staff set invitation_expires_at=null, updated_at=now() where user_id=(select auth.uid()) and status='active' and invited_at is not null and invitation_expires_at>now(); if not found then raise exception 'Invitation is expired or already accepted'; end if; insert into public.wantiss_admin_audit_log(actor_user_id,action,resource_type,resource_id,reason) values ((select auth.uid()),'staff_invitation_accepted','staff',(select auth.uid())::text,'Email verified and password activated'); end $$; revoke all on function public.wantiss_admin_accept_invitation() from public,anon; grant execute on function public.wantiss_admin_accept_invitation() to authenticated;